  "pairs": [
    {"reference_id": "R1", "candidate_id": "C2", "target_relation": "uncertain", "reference_claim_ids": ["R1.S1"], "reference_evidence": "The cords fall from his hands and slide to the right on top of him unnaturally.", "candidate_evidence": "resistance band abruptly warps and repositions", "basis": "insufficient", "reason_ko": "참조의 줄이 손에서 떨어져 오른쪽으로 미끄러진다는 설명과 후보의 밴드가 뒤틀리며 재배치된다는 설명은 동일한 줄의 부자연스러운 거동에 대한 서로 다른 묘사일 가능성이 있으나, 주어진 텍스트 증거만으로는 동일 사건인지 분리되는 별개 사건인지 확정하기에 정보가 부족합니다.", "separation_basis": "insufficient"},
    {"reference_id": "R1", "candidate_id": "C3", "target_relation": "different", "reference_claim_ids": ["R1.S1"], "reference_evidence": "The cords fall from his hands and slide to the right on top of him unnaturally.", "candidate_evidence": "The green resistance band spontaneously dissolves from hands and snaps unnaturally into a pile on the floor.", "basis": "explicit_contradiction", "reason_ko": "참조는 줄이 사람의 몸 위에서 오른쪽으로 미끄러진다고 명시하는 반면, 후보는 밴드가 손에서 녹아 없어지며(dissolves) 바닥에 더미 형태로 갑자기 이동한다고 주장하여 서로 물리적 이동 및 거동 양상이 양립 불가능하게 상충합니다.", "separation_basis": "contradictory_claim"},
    {"reference_id": "R1", "candidate_id": "C4", "target_relation": "different", "reference_claim_ids": ["R1.S1"], "reference_evidence": "The cords fall from his hands and slide to the right on top of him unnaturally.", "candidate_evidence": "dissolving into green motion blur and disappearing into thin air rather than recoiling physically", "basis": "explicit_contradiction", "reason_ko": "참조는 줄이 남아 몸 위에서 미끄러지는 물리적 움직임을 기술하지만, 후보는 공중에서 모션 블러로 분해되어 완전히 사라져버렸다고(disappearing into thin air) 기술하여 두 불만 사항의 핵심 상태가 명백히 상충합니다.", "separation_basis": "contradictory_claim"},
    {"reference_id": "R1", "candidate_id": "C5", "target_relation": "different", "reference_claim_ids": ["R1.S1"], "reference_evidence": "The cords fall from his hands and slide to the right on top of him unnaturally.", "candidate_evidence": "A pile of resistance bands or dark handles spontaneously materializes on the gym floor next to the blue mat", "basis": "explicit_separation", "reason_ko": "참조는 사람의 손에서 떨어져 몸 위로 미끄러지는 줄의 움직임에 대한 불만이지만, 후보는 사람이 일어난 뒤 매트 옆 체육관 바닥에 밴드 더미가 자연발생(materializes)하는 현상을 다루어 명백히 별개의 대상 및 현상(발생)입니다.", "separation_basis": "distinct_occurrence"},
    {"reference_id": "R1", "candidate_id": "C6", "target_relation": "different", "reference_claim_ids": ["R1.S1"], "reference_evidence": "The cords fall from his hands and slide to the right on top of him unnaturally.", "candidate_evidence": "공중으로 튀었다가 바닥으로 떨어집니다.", "basis": "explicit_contradiction", "reason_ko": "참조는 줄이 사람의 몸 위에서 오른쪽으로 미끄러진다고 명시한 반면, 후보는 밴드가 공중으로 튀었다가 바닥으로 떨어졌다고 기술하여 줄이 이동한 경로와 착지 지점에 대한 주장이 서로 모순됩니다.", "separation_basis": "contradictory_claim"}
  ]
}
